from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 4))
    m = draw(st.integers(1, 8))
    lines = [f"{n} {m}"]
    for _ in range(n):
        a = draw(st.integers(1, m))
        b = draw(st.integers(1, m))
        L, R = min(a, b), max(a, b)
        lines.append(f"{L} {R}")
    return "\n".join(lines) + "\n"

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 2:
            return False
        n, m = int(t[0]), int(t[1])
        if not (1 <= n <= 2 * 10**5 and 1 <= m <= 2 * 10**5):
            return False
        if len(t) != 2 + 2 * n:
            return False
        vals = [int(x) for x in t[2:]]
        for i in range(n):
            L, R = vals[2 * i], vals[2 * i + 1]
            if not (1 <= L <= R <= m):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n, m = int(t[0]), int(t[1])
    segs = [(int(t[2 + 2 * i]), int(t[3 + 2 * i])) for i in range(n)]
    cnt = 0
    for l in range(1, m + 1):
        for r in range(l, m + 1):
            ok = True
            for L, R in segs:
                if l <= L and R <= r:
                    ok = False
                    break
            if ok:
                cnt += 1
    return f"{cnt}\n"
